51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    /** Minimal syntactic check for an email address: a non-empty local part, a single
62	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
63	    private static final Pattern EMAIL_PATTERN =
64	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final TelephoneNormalizer telephoneNormalizer;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper,
80	                                 TelephoneNormalizer telephoneNormalizer) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	        this.telephoneNormalizer = telephoneNormalizer;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        if (owner.getRegistrationDate() == null) {
119	            owner.setRegistrationDate(LocalDate.now());
120	        }
121	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
122	        if (telephone == null) {
123	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	        }
125	        owner.setTelephone(telephone);
126	        String email = owner.getEmail();
127	        if (email != null) {
128	            email = email.trim();
129	            if (!EMAIL_PATTERN.matcher(email).matches()) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email.toLowerCase(Locale.ROOT));
133	        }
134	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
135	            .map(Owner::getTelephone)
136	            .filter(Objects::nonNull)
137	            .map(telephoneNormalizer::normalize)
138	            .anyMatch(telephone::equals);
139	        if (telephoneInUse) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        this.clinicService.saveOwner(owner);
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
152	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
153	        if (currentOwner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        currentOwner.setAddress(ownerFieldsDto.getAddress());
157	        currentOwner.setCity(ownerFieldsDto.getCity());
158	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
159	        currentOwner.setLastName(ownerFieldsDto.getLastName());
160	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
161	        this.clinicService.saveOwner(currentOwner);
162	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Transactional
167	    @Override
168	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        this.clinicService.deleteOwner(owner);
174	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        HttpHeaders headers = new HttpHeaders();
185	        Pet pet = petMapper.toPet(petFieldsDto);
186	        owner.setId(ownerId);
187	        pet.setOwner(owner);
188	        pet.getType().setName(null);
189	        this.clinicService.savePet(pet);
190	        PetDto petDto = petMapper.toPetDto(pet);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
192	            .buildAndExpand(pet.getId()).toUri());
193	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
199	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
200	        if (currentOwner != null) {
201	            Pet currentPet = this.clinicService.findPetById(petId);
202	            if (currentPet != null) {
203	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
204	                currentPet.setName(petFieldsDto.getName());
205	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
206	                this.clinicService.savePet(currentPet);
207	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	            }
209	        }
210	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	    }
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
216	        HttpHeaders headers = new HttpHeaders();
217	        Visit visit = visitMapper.toVisit(visitFieldsDto);
218	        Pet pet = new Pet();
219	        pet.setId(petId);
